const ARRIVAL_STATEMENTS: Record<string, { kind: "log" | "set"; add_sql: string; del_sql: string | null }> = {
  changed_file: { kind: "set", add_sql: `INSERT OR IGNORE INTO "changed_file" ("path") VALUES (?)`, del_sql: `DELETE FROM "changed_file" WHERE "path" = ?` },
  unwrap_hit: { kind: "set", add_sql: `INSERT OR IGNORE INTO "unwrap_hit" ("path", "line_no", "col", "end_col") VALUES (?, ?, ?, ?)`, del_sql: `DELETE FROM "unwrap_hit" WHERE "path" = ? AND "line_no" = ? AND "col" = ? AND "end_col" = ?` },
};

function arrival_statement(arrival: IArrivalRow): SqlStatement {
  const template = ARRIVAL_STATEMENTS[arrival.rel];
  if (template === undefined) {
    throw new Error(`unwrap_below_budget_silent: tick received an arrival for undeclared rel '${arrival.rel}'`);
  }
  if (arrival.sign === "del") {
    if (template.kind === "log") {
      throw new Error(`unwrap_below_budget_silent: retract from log rel '${arrival.rel}' (engine.pl retract_from_log)`);
    }
    if (template.del_sql === null) {
      throw new Error(`unwrap_below_budget_silent: rel '${arrival.rel}' has no delete statement`);
    }
    return { sql: template.del_sql, args: bind_args(arrival.row) };
  }
  return { sql: template.add_sql, args: bind_args(arrival.row) };
}

function apply_arrivals(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<unknown> {
  const statements: SqlStatement[] = arrivals.map(arrival_statement);
  return seam.runner.batch(seam.db, statements);
}

